import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../Styles/ApplicantsJob.css";
import { logout } from "../Features/UserSlice";

const ApplicantsJob = () => {
  const [applications, setApplications] = useState([]);
  const navigate = useNavigate();

  // Protect route — only company can access
  useEffect(() => {
    const role = localStorage.getItem("role");
    if (role !== "company") navigate("/login");
  }, [navigate]);

  // Load all applications
  useEffect(() => {
    axios
      .get("http://localhost:3001/applications/all")
      .then((res) => setApplications(res.data))
      .catch((err) => console.error("Error fetching applications:", err));
  }, []);

  // Update application status
  const updateStatus = async (id, status) => {
    try {
      await axios.put(`http://localhost:3001/applications/${id}/status`, {
        status,
      });
      alert(`Status changed to ${status}`);
      setApplications((prev) =>
        prev.map((a) => (a._id === id ? { ...a, status } : a))
      );
    } catch {
      alert("Error updating status");
    }
  };

  return (
    <div className="applicants-page">
      <h1 className="applicants-title">
        Job <span className="accent">Applicants</span>
      </h1>

      {applications.length === 0 ? (
        <p>No applicants yet.</p>
      ) : (
        <table className="applicants-table">
          <thead>
            <tr>
              <th>Applicant Name</th>
              <th>Email</th>
              <th>Job Title</th>
              <th>Organization</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {applications.map((app) => (
              <tr key={app._id}>
                <td>{app.applicantName}</td>
                <td>{app.applicantEmail}</td>
                <td>{app.jobTitle}</td>
                <td>{app.organization}</td>
                <td
                  className={`status ${
                    app.status === "Accepted"
                      ? "accepted"
                      : app.status === "Rejected"
                      ? "rejected"
                      : "pending"
                  }`}
                >
                  {app.status}
                </td>
                <td>
                  <button
                    onClick={() => updateStatus(app._id, "Accepted")}
                    className="accept-btn"
                  >
                    Accept
                  </button>
                  <button
                    onClick={() => updateStatus(app._id, "Rejected")}
                    className="reject-btn"
                  >
                    Reject
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ApplicantsJob;
